package dev.zomboidmelee.boxing;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;
/** Renders the existing TaCZ door-kick timeline inside the bare-hand renderer that replaces RenderHandEvent. */
public final class DoorFoot29 {
 public static double progress(Object p){try{return R.num(R.call(R.type("com.locknar.taczammocheck.tactical.client.KickAnimationClient"),"getFirstPersonKickProgress",((Number)R.call(p,"getId")).intValue()));}catch(IllegalStateException absent){return -1;}}
 public record Rig(Foot24.Point hip,Foot24.Point knee,Foot24.Point ankle,double pitch){}
 static Rig rig(double t){double enter=Motion20.smooth(Math.min(t/.14,(1-t)/.18)),hit=Motion20.track(t,new double[]{0,.16,.38,.53,.72,1},new double[]{0,.18,1,1,.45,0});return new Rig(new Foot24.Point(.36,-.90,.08),new Foot24.Point(.28,-.72+.35*enter,-.18-.20*hit),new Foot24.Point(.20,-1.02+.68*enter,-.12-1.0*hit),65*hit);}
 public static boolean draw(Object stack,Object buffers,int light,Object p){Object mc=BoxingClient16.mc();if(!Action19.firstPerson(mc))return false;double phase=progress(p);if(phase<0||phase>=1)return false;drawAt((PoseStack)stack,buffers,light,p,phase);return true;}
 static void drawAt(PoseStack pose,Object buffers,int light,Object player,double phase){Rig r=rig(phase);Object skin=StompMesh21.consumer(buffers,R.call(R.call(player,"getSkin"),"texture"));pose.pushPose();try{Foot24.segment(pose,StompMesh21.THIGH,skin,light,r.hip,r.knee,7/16d);Foot24.segment(pose,StompMesh21.PANTS_THIGH,skin,light,r.hip,r.knee,7/16d);Foot24.segment(pose,StompMesh21.SHIN,skin,light,r.knee,r.ankle,5/16d);Foot24.segment(pose,StompMesh21.PANTS_SHIN,skin,light,r.knee,r.ankle,5/16d);pose.pushPose();try{pose.translate(r.ankle.x(),r.ankle.y(),r.ankle.z());pose.scale(1,-1,1);pose.mulPose(Axis.XP.rotationDegrees((float)r.pitch));boolean boots=false;try{boots=!R.yes(R.call(R.call(player,"getItemBySlot",R.get(R.type("net.minecraft.world.entity.EquipmentSlot"),"FEET")),"isEmpty"));}catch(IllegalStateException unsupported){}if(boots){Object tex=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_global_melee","textures/entity/stomp_boot.png");StompMesh21.drawPart(StompMesh21.BOOT,pose,StompMesh21.consumer(buffers,tex),light);}else StompMesh21.drawPart(StompMesh21.FOOT,pose,skin,light);}finally{pose.popPose();}}finally{pose.popPose();}}
}
